/// <summary>
/// A half-open region of story source. Lines and columns are 1-based. `file` names the source
/// file when it is NOT the file handed to `compile()`: an imported fragment's spans carry the
/// import path as the author wrote it plus `.chord` (`regions/harbor.chord`), relative to the
/// main file's directory — the same string the import resolver receives. Absent means the main
/// file. It is stamped at splice time, never by the lexer or parser (ADR-251 D6, amended
/// 2026-08-22).
/// </summary>
public sealed record DiagnosticSpan
{
    /// <summary>Source file, relative to the main file's directory; absent = the main file.</summary>
    [JsonPropertyName("file")]
    public string? File { get; init; }

    /// <summary>1-based line of the first character.</summary>
    [JsonPropertyName("line")]
    public required int Line { get; init; }

    /// <summary>1-based column of the first character.</summary>
    [JsonPropertyName("column")]
    public required int Column { get; init; }

    /// <summary>1-based line of the last character (inclusive).</summary>
    [JsonPropertyName("endLine")]
    public required int EndLine { get; init; }

    /// <summary>1-based column just past the last character.</summary>
    [JsonPropertyName("endColumn")]
    public required int EndColumn { get; init; }
}

/// <summary>
